import math

def check_integer_sum(a, b):
    K = 1001
    try:
        # The expression to check is: sqrt(1001/a) + sqrt(1001/b) + sqrt(1001)
        s = math.sqrt(K / a) + math.sqrt(K / b) + math.sqrt(K)

        # Check if s is close to an integer within a small tolerance (e.g., 1e-9)
        nearest_integer = round(s)
        tolerance = 1e-9

        if abs(s - nearest_integer) < tolerance:
            return True, s
        else:
            return False, s
    except ValueError:
        # This handles cases where a or b might be non-positive, though the loop constraints prevent this.
        return False, None

solutions = []
limit = 1001
print(f"Checking triples (a, b) for 1 <= a, b <= {limit}...")

# Iterate over all pairs (a, b)
for a in range(1, limit + 1):
    for b in range(1, limit + 1):
        is_integer, value = check_integer_sum(a, b)
        if is_integer:
            solutions.append((a, b, value))

print("\n--- Results ---")
if solutions:
    print(f"Found {len(solutions)} solutions:")
    for a, b, val in solutions:
        print(f"({a}, {b}) -> Sum = {val:.6f}")
else:
    print("No integer solutions found for 1 <= a, b <= 1001.")
